[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>DeployCloud Blog — Discover the latest in web development</title>
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --dark: #171717;
      --accent: #0072F5;
      --accent-hover: #0062D6;
      --bg: #FAFAFA;
      --bg-white: #FFFFFF;
      --border: #E5E5E5;
      --border-light: #F0F0F0;
      --text: #171717;
      --text-secondary: #525252;
      --text-tertiary: #8A8A8A;
      --shadow-sm: 0 1px 3px rgba(0,0,0,0.06);
      --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
      --shadow-lg: 0 8px 30px rgba(0,0,0,0.1);
      --radius: 12px;
      --radius-sm: 8px;
      --radius-pill: 9999px;
      --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      --nav-height: 64px;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font);
      color: var(--text);
      background: var(--bg);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    a { color: inherit; text-decoration: none; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    img { display: block; max-width: 100%; }

    /* ─── HEADER ─── */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border);
      height: var(--nav-height);
    }

    .header-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .header-left {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    .logo {
      font-size: 18px;
      font-weight: 700;
      letter-spacing: -0.5px;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .logo-icon {
      width: 28px;
      height: 28px;
      background: var(--dark);
      border-radius: 6px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg { width: 16px; height: 16px; }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 4px;
      list-style: none;
    }

    .nav-item {
      position: relative;
    }

    .nav-link {
      display: flex;
      align-items: center;
      gap: 4px;
      padding: 8px 14px;
      font-size: 14px;
      font-weight: 500;
      color: var(--text);
      border-radius: var(--radius-sm);
      transition: background 0.15s;
      white-space: nowrap;
    }

    .nav-link:hover { background: var(--border-light); }

    .nav-link svg {
      width: 14px;
      height: 14px;
      transition: transform 0.2s;
    }

    .nav-item.open .nav-link svg { transform: rotate(180deg); }

    /* ─── MEGA MENU ─── */
    .mega-menu {
      position: absolute;
      top: calc(100% + 8px);
      left: 50%;
      transform: translateX(-50%);
      background: var(--bg-white);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      box-shadow: var(--shadow-lg);
      padding: 24px;
      opacity: 0;
      visibility: hidden;
      pointer-events: none;
      transition: opacity 0.2s, transform 0.2s;
      transform: translateX(-50%) translateY(4px);
      min-width: 580px;
    }

    .nav-item.open .mega-menu {
      opacity: 1;
      visibility: visible;
      pointer-events: auto;
      transform: translateX(-50%) translateY(0);
    }

    .mega-menu-grid {
      display: grid;
      grid-template-columns: 1fr 1fr 1fr;
      gap: 8px;
    }

    .mega-menu-grid.two-col {
      grid-template-columns: 1fr 1fr 1fr;
    }

    .mega-section-title {
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.8px;
      color: var(--text-tertiary);
      padding: 8px 12px 6px;
      margin-bottom: 2px;
    }

    .mega-item {
      display: block;
      padding: 10px 12px;
      border-radius: var(--radius-sm);
      transition: background 0.15s;
    }

    .mega-item:hover { background: var(--border-light); }

    .mega-item-title {
      font-size: 13px;
      font-weight: 600;
      color: var(--text);
      margin-bottom: 2px;
    }

    .mega-item-desc {
      font-size: 12px;
      color: var(--text-tertiary);
      line-height: 1.4;
    }

    .header-right {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .btn-ask-ai {
      display: flex;
      align-items: center;
      gap: 6px;
      padding: 7px 14px;
      font-size: 13px;
      font-weight: 600;
      color: var(--accent);
      background: rgba(0,114,245,0.08);
      border-radius: var(--radius-pill);
      transition: background 0.15s;
    }

    .btn-ask-ai:hover { background: rgba(0,114,245,0.14); }

    .btn-ask-ai svg { width: 14px; height: 14px; }

    .btn-login {
      padding: 7px 14px;
      font-size: 14px;
      font-weight: 500;
      color: var(--text);
      border-radius: var(--radius-sm);
      transition: background 0.15s;
    }

    .btn-login:hover { background: var(--border-light); }

    .btn-signup {
      padding: 7px 16px;
      font-size: 14px;
      font-weight: 600;
      color: white;
      background: var(--dark);
      border-radius: var(--radius-sm);
      transition: background 0.15s;
    }

    .btn-signup:hover { background: #333; }

    /* ─── HERO / BLOG HEADER ─── */
    .blog-hero {
      text-align: center;
      padding: 56px 24px 40px;
      max-width: 720px;
      margin: 0 auto;
    }

    .blog-hero h1 {
      font-size: 40px;
      font-weight: 700;
      letter-spacing: -1px;
      line-height: 1.15;
      margin-bottom: 12px;
    }

    .blog-hero p {
      font-size: 17px;
      color: var(--text-secondary);
      line-height: 1.6;
    }

    /* ─── CATEGORY FILTERS ─── */
    .filters-bar {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px 32px;
      display: flex;
      align-items: center;
      gap: 16px;
      flex-wrap: wrap;
    }

    .category-pills {
      display: flex;
      gap: 6px;
      flex-wrap: wrap;
    }

    .pill {
      padding: 7px 16px;
      font-size: 13px;
      font-weight: 500;
      color: var(--text-secondary);
      background: var(--bg-white);
      border: 1px solid var(--border);
      border-radius: var(--radius-pill);
      transition: all 0.15s;
      white-space: nowrap;
    }

    .pill:hover {
      border-color: var(--text-tertiary);
      color: var(--text);
    }

    .pill.active {
      background: var(--dark);
      color: white;
      border-color: var(--dark);
    }

    .search-wrap {
      position: relative;
      margin-left: auto;
    }

    .search-wrap svg {
      position: absolute;
      left: 12px;
      top: 50%;
      transform: translateY(-50%);
      width: 16px;
      height: 16px;
      color: var(--text-tertiary);
      pointer-events: none;
    }

    .search-input {
      padding: 8px 14px 8px 36px;
      font-size: 13px;
      font-family: var(--font);
      border: 1px solid var(--border);
      border-radius: var(--radius-pill);
      background: var(--bg-white);
      color: var(--text);
      width: 220px;
      outline: none;
      transition: border-color 0.15s, box-shadow 0.15s;
    }

    .search-input::placeholder { color: var(--text-tertiary); }
    .search-input:focus {
      border-color: var(--accent);
      box-shadow: 0 0 0 3px rgba(0,114,245,0.12);
    }

    /* ─── FEATURED ARTICLES ─── */
    .featured-section {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px 48px;
    }

    .featured-grid {
      display: grid;
      grid-template-columns: 1.2fr 1fr;
      grid-template-rows: auto auto;
      gap: 20px;
    }

    .featured-card {
      background: var(--bg-white);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      overflow: hidden;
      transition: box-shadow 0.2s, transform 0.2s;
      display: flex;
      flex-direction: column;
    }

    .featured-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .featured-card.main {
      grid-row: 1 / 3;
    }

    .featured-card-image {
      width: 100%;
      aspect-ratio: 16/9;
      background: linear-gradient(135deg, #0a0a2e 0%, #1a1a4e 40%, #0072F5 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }

    .featured-card.main .featured-card-image {
      aspect-ratio: auto;
      flex: 1;
    }

    .featured-card-image-content {
      padding: 32px;
      color: white;
      position: relative;
      z-index: 1;
    }

    .featured-card.main .featured-card-image-content {
      padding: 48px;
    }

    .featured-card-image::before {
      content: '';
      position: absolute;
      inset: 0;
      background: radial-gradient(circle at 30% 50%, rgba(0,114,245,0.3), transparent 70%);
    }

    .featured-image-tag {
      display: inline-block;
      padding: 4px 10px;
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.6px;
      background: rgba(255,255,255,0.15);
      border-radius: var(--radius-pill);
      margin-bottom: 16px;
      backdrop-filter: blur(8px);
    }

    .featured-card.main .featured-image-title {
      font-size: 32px;
      font-weight: 700;
      letter-spacing: -0.5px;
      line-height: 1.2;
      margin-bottom: 12px;
    }

    .featured-card:not(.main) .featured-image-title {
      font-size: 20px;
      font-weight: 700;
      letter-spacing: -0.3px;
      line-height: 1.25;
      margin-bottom: 8px;
    }

    .featured-image-excerpt {
      font-size: 14px;
      line-height: 1.5;
      opacity: 0.85;
      max-width: 500px;
    }

    .featured-card.main .featured-image-excerpt {
      font-size: 15px;
    }

    .featured-card-body {
      padding: 20px 24px;
      display: flex;
      align-items: center;
      gap: 12px;
      border-top: 1px solid var(--border-light);
    }

    .featured-card.main .featured-card-body {
      padding: 20px 28px;
    }

    .author-avatar {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 13px;
      font-weight: 600;
      color: white;
      flex-shrink: 0;
    }

    .author-info {
      display: flex;
      flex-direction: column;
    }

    .author-name {
      font-size: 13px;
      font-weight: 600;
    }

    .author-date {
      font-size: 12px;
      color: var(--text-tertiary);
    }

    /* Stats bar inside featured */
    .stats-bar {
      background: var(--bg-white);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 24px 28px;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 16px;
      margin-top: 20px;
    }

    .stat-item {
      text-align: center;
    }

    .stat-value {
      font-size: 22px;
      font-weight: 700;
      color: var(--accent);
      letter-spacing: -0.5px;
    }

    .stat-label {
      font-size: 12px;
      color: var(--text-tertiary);
      margin-top: 4px;
      line-height: 1.3;
    }

    /* ─── LATEST NEWS ─── */
    .latest-section {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px 48px;
    }

    .section-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 24px;
    }

    .section-title {
      font-size: 22px;
      font-weight: 700;
      letter-spacing: -0.3px;
    }

    .news-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
    }

    .news-card {
      background: var(--bg-white);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      overflow: hidden;
      transition: box-shadow 0.2s, transform 0.2s;
      display: flex;
      flex-direction: column;
    }

    .news-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .news-card-image {
      width: 100%;
      aspect-ratio: 16/9;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }

    .news-card-image.gradient-1 {
      background: linear-gradient(135deg, #1a1a3e, #2d1b69, #0072F5);
    }
    .news-card-image.gradient-2 {
      background: linear-gradient(135deg, #0f2027, #203a43, #2c5364);
    }
    .news-card-image.gradient-3 {
      background: linear-gradient(135deg, #1e3c72, #2a5298, #0072F5);
    }
    .news-card-image.gradient-4 {
      background: linear-gradient(135deg, #0c0c1d, #1a1a3e, #6c3caf);
    }
    .news-card-image.gradient-5 {
      background: linear-gradient(135deg, #141e30, #243b55, #0072F5);
    }
    .news-card-image.gradient-6 {
      background: linear-gradient(135deg, #1f1c2c, #928dab, #0072F5);
    }
    .news-card-image.gradient-7 {
      background: linear-gradient(135deg, #0f0c29, #302b63, #24243e);
    }
    .news-card-image.gradient-8 {
      background: linear-gradient(135deg, #16222e, #3a6073, #0072F5);
    }

    .news-card-image-icon {
      font-size: 40px;
      opacity: 0.3;
    }

    .news-card-content {
      padding: 20px;
      flex: 1;
      display: flex;
      flex-direction: column;
    }

    .card-category {
      display: inline-block;
      padding: 3px 10px;
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      color: var(--accent);
      background: rgba(0,114,245,0.08);
      border-radius: var(--radius-pill);
      margin-bottom: 10px;
      align-self: flex-start;
    }

    .card-category.engineering { color: #7c3aed; background: rgba(124,58,237,0.08); }
    .card-category.customers { color: #059669; background: rgba(5,150,105,0.08); }
    .card-category.security { color: #dc2626; background: rgba(220,38,38,0.08); }
    .card-category.community { color: #d97706; background: rgba(217,119,6,0.08); }
    .card-category.company-news { color: #0891b2; background: rgba(8,145,178,0.08); }

    .card-title {
      font-size: 17px;
      font-weight: 650;
      letter-spacing: -0.2px;
      line-height: 1.3;
      margin-bottom: 8px;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .card-excerpt {
      font-size: 14px;
      color: var(--text-secondary);
      line-height: 1.55;
      flex: 1;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .card-footer {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-top: 16px;
      padding-top: 14px;
      border-top: 1px solid var(--border-light);
    }

    .card-author-avatar {
      width: 28px;
      height: 28px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 11px;
      font-weight: 600;
      color: white;
      flex-shrink: 0;
    }

    .card-author-info {
      display: flex;
      flex-direction: column;
    }

    .card-author-name {
      font-size: 12px;
      font-weight: 600;
    }

    .card-date {
      font-size: 11px;
      color: var(--text-tertiary);
    }

    /* ─── NO RESULTS ─── */
    .no-results {
      grid-column: 1 / -1;
      text-align: center;
      padding: 64px 24px;
    }

    .no-results-icon {
      font-size: 48px;
      margin-bottom: 16px;
      opacity: 0.3;
    }

    .no-results h3 {
      font-size: 18px;
      font-weight: 600;
      margin-bottom: 8px;
    }

    .no-results p {
      font-size: 14px;
      color: var(--text-tertiary);
      max-width: 400px;
      margin: 0 auto;
    }

    /* ─── SHOW MORE ─── */
    .show-more-wrap {
      text-align: center;
      padding: 20px 0 0;
    }

    .btn-show-more {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 12px 28px;
      font-size: 14px;
      font-weight: 600;
      color: var(--text);
      background: var(--bg-white);
      border: 1px solid var(--border);
      border-radius: var(--radius-sm);
      transition: all 0.15s;
    }

    .btn-show-more:hover {
      border-color: var(--text-tertiary);
      box-shadow: var(--shadow-sm);
    }

    .btn-show-more svg { width: 16px; height: 16px; }

    .btn-show-more.hidden { display: none; }

    /* ─── CTA BANNER ─── */
    .cta-section {
      background: var(--dark);
      color: white;
      padding: 80px 24px;
    }

    .cta-inner {
      max-width: 1280px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 64px;
      align-items: center;
    }

    .cta-block h2 {
      font-size: 30px;
      font-weight: 700;
      letter-spacing: -0.5px;
      line-height: 1.2;
      margin-bottom: 24px;
    }

    .cta-block h2 strong {
      color: var(--accent);
    }

    .cta-buttons {
      display: flex;
      gap: 12px;
      flex-wrap: wrap;
    }

    .btn-primary {
      padding: 12px 28px;
      font-size: 14px;
      font-weight: 600;
      color: white;
      background: var(--accent);
      border-radius: var(--radius-sm);
      transition: background 0.15s;
    }

    .btn-primary:hover { background: var(--accent-hover); }

    .btn-secondary {
      padding: 12px 28px;
      font-size: 14px;
      font-weight: 600;
      color: white;
      background: transparent;
      border: 1px solid rgba(255,255,255,0.25);
      border-radius: var(--radius-sm);
      transition: all 0.15s;
    }

    .btn-secondary:hover {
      border-color: rgba(255,255,255,0.5);
      background: rgba(255,255,255,0.05);
    }

    .enterprise-block {
      background: rgba(255,255,255,0.05);
      border: 1px solid rgba(255,255,255,0.1);
      border-radius: var(--radius);
      padding: 32px;
    }

    .enterprise-block p {
      font-size: 15px;
      color: rgba(255,255,255,0.7);
      line-height: 1.6;
      margin-bottom: 20px;
    }

    /* ─── FOOTER ─── */
    .footer {
      background: var(--dark);
      color: rgba(255,255,255,0.7);
      padding: 64px 24px 32px;
      border-top: 1px solid rgba(255,255,255,0.08);
    }

    .footer-inner {
      max-width: 1280px;
      margin: 0 auto;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 32px;
      margin-bottom: 48px;
    }

    .footer-col h4 {
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.8px;
      color: rgba(255,255,255,0.4);
      margin-bottom: 16px;
    }

    .footer-col ul {
      list-style: none;
    }

    .footer-col li {
      margin-bottom: 8px;
    }

    .footer-col a {
      font-size: 13px;
      color: rgba(255,255,255,0.6);
      transition: color 0.15s;
    }

    .footer-col a:hover { color: white; }

    .footer-bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding-top: 24px;
      border-top: 1px solid rgba(255,255,255,0.08);
    }

    .footer-status {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 12px;
      color: rgba(255,255,255,0.4);
    }

    .status-dot {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: #22c55e;
    }

    .footer-copy {
      font-size: 12px;
      color: rgba(255,255,255,0.3);
    }

    .footer-social {
      display: flex;
      gap: 16px;
    }

    .footer-social a {
      color: rgba(255,255,255,0.4);
      transition: color 0.15s;
    }

    .footer-social a:hover { color: white; }

    /* ─── RESPONSIVE ─── */
    @media (max-width: 1024px) {
      .news-grid { grid-template-columns: repeat(2, 1fr); }
      .stats-bar { grid-template-columns: repeat(2, 1fr); }
      .footer-grid { grid-template-columns: repeat(3, 1fr); }
      .mega-menu { min-width: 480px; }
    }

    @media (max-width: 768px) {
      .blog-hero h1 { font-size: 28px; }
      .featured-grid {
        grid-template-columns: 1fr;
        grid-template-rows: auto;
      }
      .featured-card.main { grid-row: auto; }
      .featured-card.main .featured-image-title { font-size: 24px; }
