    const INITIAL_COUNT = 8;
    let visibleCount = INITIAL_COUNT;
    let activeCategory = 'all';
    let searchQuery = '';

    /* ═══ RENDER ═══ */
    function createCardHTML(post) {
      const catClass = post.category !== 'general' ? post.category : '';
      const catLabel = post.category === 'general' ? 'General' :
                       post.category === 'company-news' ? 'Company News' :
                       post.category.charAt(0).toUpperCase() + post.category.slice(1);
      return `
        <article class="news-card" data-categories="${post.category}" data-title="${post.title.toLowerCase()}">
          <div class="news-card-image ${post.gradient}">
            <span class="news-card-image-icon">&#9670;</span>
          </div>
          <div class="news-card-content">
            <span class="card-category ${catClass}">${catLabel}</span>
            <h3 class="card-title">${post.title}</h3>
            <p class="card-excerpt">${post.excerpt}</p>
            <div class="card-footer">
              <div class="card-author-avatar" style="background:${post.authorColor}">${post.authorInitials}</div>
              <div class="card-author-info">
                <span class="card-author-name">${post.author}</span>
                <span class="card-date">${post.date}</span>
              </div>
            </div>
          </div>
        </article>
      `;
    }

    function renderGrid() {
      const grid = document.getElementById('newsGrid');
      const posts = allPosts.slice(0, visibleCount);

      // Filter
      let filtered = posts;
      if (activeCategory !== 'all') {
        filtered = filtered.filter(p => p.category === activeCategory);
      }
      if (searchQuery) {
        const q = searchQuery.toLowerCase();
        filtered = filtered.filter(p =>
          p.title.toLowerCase().includes(q) ||
          p.excerpt.toLowerCase().includes(q) ||
          p.author.toLowerCase().includes(q) ||
          p.category.toLowerCase().includes(q)
        );
      }

      if (filtered.length === 0) {
        grid.innerHTML = `
          <div class="no-results">
            <div class="no-results-icon">&#128269;</div>
            <h3>No results found</h3>
            <p>No results found at this time. Try again with a different keyword.</p>
          </div>
        `;
      } else {
        grid.innerHTML = filtered.map(createCardHTML).join('');
      }

      // Also filter featured section
      filterFeatured();
      // Show/hide "show more" button
      updateShowMore();
    }

    function filterFeatured() {
      const cards = document.querySelectorAll('.featured-card');
      const statsBar = document.getElementById('statsBar');
      let anyVisible = false;

      cards.forEach(card => {
        const cats = card.dataset.categories;
        const title = card.dataset.title.toLowerCase();
        let show = true;

        if (activeCategory !== 'all' && cats !== activeCategory) {
          show = false;
        }
        if (searchQuery) {
          const q = searchQuery.toLowerCase();
          if (!title.includes(q) && !cats.includes(q)) {
            show = false;
          }
        }

        card.classList.toggle('hidden-card', !show);
        if (show) anyVisible = true;
      });

      // Stats bar visibility tied to the "Agentic Infrastructure" featured card
      const agenticCard = document.querySelector('[data-title="Agentic Infrastructure"]');
      if (agenticCard) {
        statsBar.style.display = agenticCard.classList.contains('hidden-card') ? 'none' : '';
      }
    }

    function updateShowMore() {
      const btn = document.getElementById('showMoreBtn');
      if (visibleCount >= allPosts.length) {
        btn.classList.add('hidden');
      } else {
        btn.classList.remove('hidden');
      }
    }

    /* ═══ CATEGORY PILLS ═══ */
    document.querySelectorAll('.pill').forEach(pill => {
      pill.addEventListener('click', () => {
        document.querySelectorAll('.pill').forEach(p => {
          p.classList.remove('active');
          p.setAttribute('aria-selected', 'false');
        });
        pill.classList.add('active');
        pill.setAttribute('aria-selected', 'true');
        activeCategory = pill.dataset.category;
        renderGrid();
      });
    });

    /* ═══ SEARCH ═══ */
    const searchInput = document.getElementById('searchInput');
    let searchTimeout;
    searchInput.addEventListener('input', () => {
      clearTimeout(searchTimeout);
      searchTimeout = setTimeout(() => {
        searchQuery = searchInput.value.trim();
        renderGrid();
      }, 200);
    });

    /* ═══ SHOW MORE ═══ */
    document.getElementById('showMoreBtn').addEventListener('click', () => {
      visibleCount = Math.min(visibleCount + 4, allPosts.length);
      renderGrid();
    });

    /* ═══ NAV DROPDOWNS ═══ */
    document.querySelectorAll('.nav-item[data-dropdown]').forEach(item => {
      const btn = item.querySelector('.nav-link');
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const isOpen = item.classList.contains('open');
        // Close all
        document.querySelectorAll('.nav-item').forEach(i => {
          i.classList.remove('open');
          const b = i.querySelector('.nav-link');
          if (b) b.setAttribute('aria-expanded', 'false');
        });
        if (!isOpen) {
          item.classList.add('open');
          btn.setAttribute('aria-expanded', 'true');
        }
      });
    });

    // Close dropdowns on outside click
    document.addEventListener('click', (e) => {
      if (!e.target.closest('.nav-item[data-dropdown]')) {
        document.querySelectorAll('.nav-item').forEach(i => {
          i.classList.remove('open');
          const b = i.querySelector('.nav-link');
          if (b) b.setAttribute('aria-expanded', 'false');
        });
      }
    });

    // Close on Escape
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        document.querySelectorAll('.nav-item').forEach(i => {
          i.classList.remove('open');
          const b = i.querySelector('.nav-link');
          if (b) b.setAttribute('aria-expanded', 'false');
        });
      }
    });

    /* ═══ INIT ═══ */
    renderGrid();
  </script>
